/// <summary>
/// N.Freidenberger 30.04.24
/// </summary>
/// <returns></returns>
protected QueryRun getLateSelectionQuery()
{
    QueryRun latestQueryRun =   next   getLateSelectionQuery();
    FormLetterContract  formLetterContract = this.formLetterContract;
    TransDate           lastPackingSlipDate;

    if (formLetterContract is SalesFormLetterInvoiceContract)
    {
        SalesFormLetterInvoiceContract  salesFormletterInvoiceContract = formLetterContract as salesFormletterInvoiceContract;

        SalesParmUpdate     salesParmUpdate = salesFormletterInvoiceContract.parmParmUpdate();

        Query   query = latestQueryRun.query();
        if(salesParmUpdate.AVAShiftDays != -1)
        {
            lastPackingSlipDate = systemDateGet() - salesParmUpdate.AVAShiftDays;

            QueryBuildDataSource        salesTableDS = query.dataSourceTable(tableNum(SalesTable));
            if(salesTableDS)
            {
               // QueryBuildDataSource        salesPackingSlipLinkDS = salesTableDS.addDataSource(tableNum(custPackingSlipSalesLink));
              //  salesPackingSlipLinkDS.joinMode(JoinMode::InnerJoin);
               // salesPackingSlipLinkDS.addLink(fieldnum(SalesTable,SalesId),fieldNum(CustPackingSlipSalesLink,OrigSalesId));
               SysQuery::findOrCreateRange(salesTableDS,fieldnum(SalesTable,DeliveryDate)).value(SysQuery::range(datenull(),lastPackingSlipDate));
               // SysQuery::findOrCreateRange(salesPackingSlipLinkDS,fieldnum(custPackingSlipSalesLink,DeliveryDate)).value(SysQuery::range(datenull(),lastPackingSlipDate));
            }    
           /* QueryBuildDataSource            custPackingSlipTransDS = query.dataSourceTable(tableNum(CUstPackingSlipTrans));
            if (custPackingSlipTransDS)
            {
                SysQuery::findOrCreateRange(custPackingSlipTransDS,fieldnum(CustPackingSlipTrans,DeliveryDate)).value(SysQuery::range(datenull(),lastPackingSlipDate));
            }    */
        }

    }
    return new QueryRun(latestQueryRun.pack());
}
